$nom = trim(file_get_contents('/var/spool/app/prochain-client.txt'));
if (!preg_match('/^[a-z0-9-]{1,32}$/', $nom)) { fwrite(STDERR, "Nom de client refuse\n"); exit(1); }
$archive = "/sauvegardes/$nom.tgz";
// proc_open avec un TABLEAU : aucun shell n'est ouvert, donc aucun metacaractere n'a de sens.
// Le "--" termine la liste des options : un nom commencant par - reste un operande.
$proc = proc_open(['/bin/tar', '-czf', $archive, '--', "/var/www/clients/$nom"], [2 => ['pipe', 'w']], $pipes);
fclose($pipes[2]);
if (proc_close($proc) !== 0) { exit(1); }   // le code de retour declenche l'alerte
